-- رابط الخطوة التالية في صفحة التأشيرة (محروس)
UPDATE articles SET details = details || '<p style="margin-top:1rem;">وبعد وصولك بالتأشيرة تبدأ المرحلة الثانية: <a href="/article/student-residence-permit-2026"><strong>إقامة الطالب من الطلب إلى التجديد — الدليل الكامل ←</strong></a></p>', last_update = CURRENT_DATE
WHERE slug = 'turkey-study-visa-syrians-2026' AND details NOT LIKE '%student-residence-permit-2026%';

-- ═══════════════════════════════════════════════════════════════════════════
DO $check$
DECLARE n int;
BEGIN
    SELECT count(*) INTO n FROM articles
     WHERE slug = 'student-residence-permit-2026' AND status = 'approved'
       AND details LIKE '%e-ikamet%' AND details LIKE '%60 يوماً%'
       AND details LIKE '%الأشهر الثلاثة الأولى%';
    IF n <> 1 THEN RAISE EXCEPTION 'the student guide did not land'; END IF;

    SELECT count(*) INTO n FROM articles WHERE slug = 'student-residence-permit-2026';
    IF n <> 1 THEN RAISE EXCEPTION 'duplicate slug'; END IF;

    SELECT count(*) INTO n FROM articles
     WHERE slug = 'turkey-study-visa-syrians-2026' AND details LIKE '%student-residence-permit-2026%';
    IF n <> 1 THEN RAISE EXCEPTION 'the visa-page link did not land'; END IF;
END
$check$;

SELECT 'student guide live (e-ikamet + 60-day window + GSS window)' AS البند,
       (details LIKE '%Müracaat%')::text AS النتيجة
FROM articles WHERE slug = 'student-residence-permit-2026'
UNION ALL
SELECT 'no 2023-era tourist-switch advice, comparison linked instead',
       (details LIKE '%tourist-vs-student-residence-2025%')::text
FROM articles WHERE slug = 'student-residence-permit-2026'
UNION ALL
SELECT 'visa page links the next step', (details LIKE '%student-residence-permit-2026%')::text
FROM articles WHERE slug = 'turkey-study-visa-syrians-2026';
